// contract: this region contains no OpenMP, no parallelism -> aggressive opt
#pragma omp assume no_openmp no_parallelism
{ /* hot serial kernel */ }

// fail the build if compiled without the needed device feature
#pragma omp requires unified_shared_memory

// emit a fatal compile-time error from a metadirective fallback
#pragma omp error at(compilation) severity(fatal) message("no supported target")
```
- **Demonstrates**: `assume` as an optimization contract, `requires` committing the unit to USM, and `error` failing the build.

```c
// tile for cache, then parallelize the inter-tile loops
#pragma omp tile sizes(64, 64)
#pragma omp parallel for collapse(2)
for (int i = 0; i < n; ++i)
  for (int j = 0; j < m; ++j) a[i][j] = b[i][j] + c[i][j];

// compose via apply: tile, then unroll the intra-tile loop
#pragma omp tile sizes(32) apply(intratile: unroll partial(4))
for (int i = 0; i < n; ++i) work(i);
```
- **Demonstrates**: `tile` feeding a `parallel for collapse`, and the `apply` clause chaining `unroll` onto the intra-tile loop generated by `tile`.

```c
// CPU: exact thread count, spread for bandwidth
#pragma omp parallel num_threads(8) proc_bind(spread) default(none) shared(a)
{ /* ... */ }

// GPU offload: the canonical teams pattern
#pragma omp target teams distribute parallel for \
            num_teams(256) thread_limit(128) map(tofrom: a[0:n])
for (int i = 0; i < n; ++i) a[i] = f(a[i]);

#pragma omp parallel
#pragma omp masked filter(0)        // only thread 0; no barrier
  printf("primary only\n");
```
- **Demonstrates**: a bound CPU team, the `target teams distribute parallel for` GPU idiom, and `masked` replacing `master`.

```c
#pragma omp parallel for schedule(dynamic, 16) reduction(+: sum) nowait
for (int i = 0; i < n; ++i) sum += expensive_irregular(i);

#pragma omp parallel
{
  #pragma omp sections
  { #pragma omp section
    phase_a();
    #pragma omp section
    phase_b(); }            // a and b run on (up to) two threads
}

// prefix sum
#pragma omp parallel for reduction(inscan, +: running)
for (int i = 0; i < n; ++i) { running += a[i]; #pragma omp scan inclusive(running) b[i] = running; }
```
- **Demonstrates**: `schedule(dynamic)` + `reduction` + `nowait` for irregular work, `sections` for task-parallel phases, and `scan` for a parallel prefix sum.

```c
// dependence-driven pipeline: the runtime orders by data flow, no barriers
#pragma omp parallel
#pragma omp single
{
  #pragma omp task depend(out: x)        x = produce();
  #pragma omp task depend(in: x, out: y) y = stage2(x);
  #pragma omp task depend(in: y)         consume(y);
}   // single's implicit barrier waits for all

// recursive tasking with a cutoff
void quicksort(int *a, int lo, int hi) {
  if (hi - lo < THRESHOLD) { serial_sort(a, lo, hi); return; }
  int p = partition(a, lo, hi);
  #pragma omp task final(hi-lo < BIG) firstprivate(lo,p) quicksort(a, lo, p-1);
  #pragma omp task final(hi-lo < BIG) firstprivate(p,hi) quicksort(a, p+1, hi);
  #pragma omp taskwait
}
```
- **Demonstrates**: `depend`-built DAG replacing barriers, and recursive `task` with `final` cutoff + `taskwait`.

```c
// hoist data, then run kernels against resident data (no per-kernel transfers)
#pragma omp target enter data map(to: a[0:n], b[0:n]) map(alloc: c[0:n])
for (int t = 0; t < nsteps; ++t) {
  #pragma omp target teams distribute parallel for
  for (int i = 0; i < n; ++i) c[i] = a[i]*b[i] + c[i];
}
#pragma omp target exit data map(from: c[0:n]) map(delete: a[0:n], b[0:n])

// device-resident function + variable
#pragma omp begin declare target
double kernel_helper(double x) { return x*x; }
#pragma omp end declare target

// async offload joined by dependence
#pragma omp target nowait depend(out: a) map(tofrom: a[0:n]) { /* ... */ }
#pragma omp taskwait depend(in: a)
```
- **Demonstrates**: data-lifetime hoisting with `target enter/exit data`, `declare target` for device functions, and async `target` joined via `depend`/`taskwait`.

